class Solution {
  public boolean scoreBalance(String s) {
    int total = 0;
    for (char c : s.toCharArray()) total += c - 'a' + 1;
    int left = 0;
    for (int i = 0; i + 1 < s.length(); i++) {
      left += s.charAt(i) - 'a' + 1;
      if (left * 2 == total) return true;
    }
    return false;
  }
}
